// The contract-derived files that are BUILD OUTPUTS, not repository content.
//
// WHY THEY ARE NOT COMMITTED (WP4 / R4, plan 2026-09-08-verification-rebuild.md)
//   Every one of them is a pure function of `packages/ui/component-contracts.json` (plus the icon
//   sources it names). Committing them bought nothing and cost a merge conflict on every sibling
//   PR that touched a component. They are regenerated by `prepare:content` in both
//   workspaces that read them, and on demand by `ensureBuildOutputs()` below.
//
// WHAT IS STILL COMMITTED, AND WHY
//   `docs/ledger/component-matrix.md`, the public skill roster, the audit register, and the
//   AGENTS.md § Numbers / README § Inventory regions are PROSE that humans and agents read
//   straight out of git without running a build. Those stay tracked and stay checked by
//   `pnpm design:derived:check`. The registry copy-in (`apps/docs/components/ui/*`) and
//   `apps/docs/public/r/*` stay committed under the locked distribution decision.

import { execFileSync } from "node:child_process";
import { existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");

/**
 * Repo-relative paths of every gitignored, contract-derived file, GROUPED BY THE WORKSPACE THAT
 * OWNS THEM. The grouping is load-bearing for turbo: a task's `outputs` can only name files under
 * its own package directory, so one shared `prepare:content` that writes all five would let a cache
 * hit in either workspace restore an incomplete set. Each workspace's script now passes
 * `--only <package>` and writes only its own files, and `turbo.json` carries a package-scoped
 * `<pkg>#prepare:content` whose `outputs` are exactly that package's list. It also removes the race
 * two parallel writers had on the same five paths.
 */
export const BUILD_OUTPUTS_BY_PACKAGE = {
  "apps/docs": [
    "apps/docs/lib/home-component-catalog.generated.ts",
    "apps/docs/components/animated-icon-gallery.generated.tsx",
  ],
};

/** Repo-relative paths of every gitignored, contract-derived file. */
export const BUILD_OUTPUTS = Object.values(BUILD_OUTPUTS_BY_PACKAGE).flat();

export const isBuildOutput = (relative) => BUILD_OUTPUTS.includes(relative);

/**
 * Generate the build outputs if any is missing — or unconditionally with `{ force: true }`, which
 * is what a verifier wants: it reconciles the GENERATOR against the contract, so a stale artefact
 * left on disk by an out-of-date `prepare:content` must not read as a contract failure. Cheap (a
 * no-op stat per file, ~90 ms for a full regeneration). Callers are the readers that can run before
 * any build in a fresh clone — today that is `verify-component-contracts.mjs`.
 */
export function ensureBuildOutputs({ force = false } = {}) {
  if (
    !force &&
    BUILD_OUTPUTS.every((relative) => existsSync(join(ROOT, relative)))
  )
    return false;
  execFileSync(
    process.execPath,
    [join(ROOT, "tooling/sync-component-derived.mjs"), "--build-outputs"],
    // STDOUT is CLOSED on purpose. Callers have parsed this process's STDOUT as JSON, and on a cold
    // clone the generator's progress line landed in front of that JSON and broke them with
    // `Unexpected token '✓'`. The generator writes progress to stderr anyway; this is the belt to
    // that suspenders.
    { cwd: ROOT, stdio: ["ignore", "ignore", "inherit"] },
  );
  return true;
}
